contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: tos and values arrays, and a flag chooseSender: if true, call transfer from the correct address by simulating via try (we cannot change msg.sender),
    // but since the checker deploys C and calls run with msg.sender = this contract, we can only observe behavior from this contract as caller.
    // We therefore assert: when this contract is not the hardcoded from address (observed via c.from()), the call must revert; if it doesn't revert then it must return true and c.from()/c.caddress() remain equal to their pre-call values.
    function run(address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length == v.length);

        // Read visible state before the call
        address before_from = c.from();
        address before_caddress = c.caddress();

        bool reverted;
        bool ret;
        try c.transfer(_tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // After-call observed getters
        address after_from = c.from();
        address after_caddress = c.caddress();

        // General rule:
        // If caller (this contract) is not equal to c.from() as observed before the call, the transfer must revert.
        // If the call did not revert then it must have returned true and the public getters from and caddress must be unchanged.
        assert((address(this) != before_from ? reverted : (!reverted && ret == true && after_from == before_from && after_caddress == before_caddress)));
    }

    receive() external payable {}
}

